import itertools, random
random.seed(7)
b = lambda p, v: p if v else 1 - p
def joint():
    pL, pN = random.uniform(.1, .9), random.uniform(.1, .9)
    pT = {(l, n): random.uniform(.05, .95) for l in (0, 1) for n in (0, 1)}
    pU = {t: random.uniform(.05, .95) for t in (0, 1)}
    pE = {l: random.uniform(.05, .95) for l in (0, 1)}
    return {(l, n, t, u, e): b(pL, l) * b(pN, n) * b(pT[l, n], t) * b(pU[t], u) * b(pE[l], e)
            for l, n, t, u, e in itertools.product((0, 1), repeat=5)}
IDX = dict(L=0, N=1, T=2, U=3, E=4)
def gap(J, x, y, z):  # max |P(x,y|z) - P(x|z)P(y|z)| over all value assignments
    P = lambda **kw: sum(p for k, p in J.items() if all(k[IDX[a]] == v for a, v in kw.items()))
    g = 0
    for zv in itertools.product((0, 1), repeat=len(z)):
        zz = dict(zip(z, zv)); pz = P(**zz)
        for xv, yv in itertools.product((0, 1), repeat=2):
            g = max(g, abs(P(**zz, **{x: xv, y: yv}) / pz - P(**zz, **{x: xv}) / pz * P(**zz, **{y: yv}) / pz))
    return g
for seed in range(3):                                   # random CPTs consistent with the DAG
    J = joint()
    for o, (x, y, z) in zip('ABCD', [('L', 'N', 'U'), ('E', 'U', 'T'), ('E', 'N', 'U'), ('L', 'U', 'E')]):
        print(seed, o, 'independent' if gap(J, x, y, z) < 1e-12 else 'DEPENDENT', round(gap(J, x, y, z), 5))
# Only B is independent for every CPT (A, C, D are dependent for generic CPTs) -> (B)

import heapq
W = {('S','A'): 4, ('S','B'): 1, ('B','A'): 2, ('A','C'): 5, ('B','C'): 9, ('A','D'): 2, ('B','D'): 7, ('C','T'): 2, ('D','T'): 7}
adj = {}
for (u, v), w in W.items(): adj.setdefault(u, []).append((v, w))
dist, par, pq, done = {'S': 0}, {}, [(0, 'S')], set()
while pq:
    d, u = heapq.heappop(pq)
    if u in done: continue
    done.add(u)
    for v, w in adj.get(u, []):
        if d + w < dist.get(v, 1e9): dist[v], par[v] = d + w, u; heapq.heappush(pq, (d + w, v))
p = ['T']
while p[-1] != 'S': p.append(par[p[-1]])
print(dist['T'], p[::-1])                                # 10 ['S','B','A','C','T'] -> (C)
def paths(u, seen):                                       # brute force: every simple S->T path
    if u == 'T': yield [u], 0; return
    for v, w in adj.get(u, []):
        for q, c in paths(v, seen | {v}): yield [u] + q, c + w
for q, c in sorted(paths('S', {'S'}), key=lambda t: t[1]): print(c, '->'.join(q))   # 10 is the unique minimum

E = {('S','A'): 2, ('S','B'): 1, ('A','C'): 1, ('A','D'): 6, ('B','C'): 4, ('B','G'): 9, ('C','D'): 2, ('D','G'): 2}
h = {'S': 3, 'A': 5, 'B': 2, 'C': 1, 'D': 2, 'G': 0}
adj = {}
for (u, v), w in E.items(): adj.setdefault(u, []).append((v, w))
def astar(reopen):
    g, par, front, closed, seq = {'S': 0}, {'S': None}, {'S': h['S']}, set(), []
    while front:
        fs = sorted(front.items(), key=lambda kv: kv[1])
        assert len(fs) == 1 or fs[0][1] != fs[1][1], 'tie'       # the stem says no ties arise
        n = fs[0][0]; del front[n]; seq.append(n)
        if n == 'G': break                                        # goal test on selection
        closed.add(n)
        for v, w in adj.get(n, []):
            ng = g[n] + w
            if v in closed:
                if reopen and ng < g[v]: g[v], par[v] = ng, n; closed.discard(v); front[v] = ng + h[v]
                continue
            if v not in g or ng < g[v]: g[v], par[v] = ng, n; front[v] = ng + h[v]
    path = ['G']
    while par[path[-1]]: path.append(par[path[-1]])
    return seq, g['G'], path[::-1]
